-- 1. เพิ่มคอลัมน์ building, size, bathroom, amenities ในตาราง rooms (ถ้ายังไม่มี)
ALTER TABLE rooms ADD COLUMN IF NOT EXISTS building VARCHAR(50);
ALTER TABLE rooms ADD COLUMN IF NOT EXISTS size VARCHAR(50);
ALTER TABLE rooms ADD COLUMN IF NOT EXISTS bathroom VARCHAR(50);
ALTER TABLE rooms ADD COLUMN IF NOT EXISTS amenities TEXT;

-- 2. เคลียร์ข้อมูลห้องพักเดิม
